import unittest
from decimal import Decimal

from billing import invoice_amount


class InvoiceAmountTests(unittest.TestCase):
    def test_valid_amounts_are_decimal_cents(self):
        self.assertEqual(invoice_amount("12"), Decimal("12.00"))
        self.assertEqual(invoice_amount(" 12.3 "), Decimal("12.30"))
        self.assertEqual(invoice_amount("0.00"), Decimal("0.00"))

    def test_invalid_strings(self):
        for value in ("", "-1", "+1", "1.", ".50", "1.234", "1e2", "1,000"):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    invoice_amount(value)

    def test_non_strings(self):
        for value in (None, 1, Decimal("1.00"), True):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    invoice_amount(value)


if __name__ == "__main__":
    unittest.main()

import unittest
from decimal import Decimal

from billing import invoice_amount


class InvoiceAmountTests(unittest.TestCase):
    def test_valid_amounts_are_normalized_to_cents(self):
        self.assertEqual(invoice_amount("12"), Decimal("12.00"))
        self.assertEqual(invoice_amount(" 12.3 "), Decimal("12.30"))
        self.assertEqual(invoice_amount("0.00"), Decimal("0.00"))

    def test_invalid_amount_strings_are_rejected(self):
        for value in ("", "-1", "+1", "1.", ".50", "1.234", "1e2", "1,000"):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    invoice_amount(value)

    def test_non_strings_are_rejected(self):
        for value in (None, 1, Decimal("1.00"), True):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    invoice_amount(value)


if __name__ == "__main__":
    unittest.main()
